+// API keys and roles. viewer: GET only. cook: also cook, waste, temperatures
+// and stock-take counts. manager: everything (and GET /audit).
+import { AppError } from "../errors.js";
+
+const COOK_WRITES = [
+  ["POST", /^\/recipes\/[^/]+\/cook$/],
+  ["POST", /^\/batches\/[^/]+\/waste$/],
+  ["POST", /^\/temperatures$/],
+  ["POST", /^\/stocktakes\/[^/]+\/counts$/],
+];
+
+/** Finds the key record for the request's Bearer token, or throws `unauthorized`. */
+export function authenticate(store, headers) {
+  const name = Object.keys(headers).find((h) => h.toLowerCase() === "authorization");
+  const m = /^Bearer\s+(\S+)\s*$/i.exec(name ? String(headers[name]) : "");
+  const found = m && (store.data.apiKeys ?? []).find((k) => k.key === m[1]);
+  if (!found) throw new AppError("unauthorized");
+  return found;
+}
+
+/** Throws `forbidden` unless the key's role may make this request. */
+export function authorize(apiKey, method, path) {
+  const { role } = apiKey;
+  const ok =
+    role === "manager" ||
+    (method === "GET" && path !== "/audit" && (role === "viewer" || role === "cook")) ||
+    (role === "cook" && COOK_WRITES.some(([m, re]) => m === method && re.test(path)));
+  if (!ok) throw new AppError("forbidden", { role, method, path });
+}
