@@ -0,0 +1,45 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { as, app } from "./helpers.js";
+
+test("no key or an unknown key is 401", async () => {
+  const { raw } = app();
+  const none = await raw({ path: "/items" });
+  assert.equal(none.status, 401);
+  assert.equal(none.body.error.code, "unauthorized");
+  const bad = await raw({ path: "/items", headers: { authorization: "Bearer nope" } });
+  assert.equal(bad.status, 401);
+});
+
+test("viewers only read", async () => {
+  const { raw } = app();
+  const viewer = as("viewer", raw);
+  assert.equal((await viewer({ path: "/items" })).status, 200);
+  const res = await viewer({ method: "POST", path: "/recipes/1/cook", body: { portions: 1 } });
+  assert.equal(res.status, 403);
+  assert.equal(res.body.error.code, "forbidden");
+  assert.equal((await viewer({ path: "/audit" })).status, 403);
+});
+
+test("cooks cook and count but do not order", async () => {
+  const { raw } = app();
+  const cook = as("cook", raw);
+  assert.equal((await cook({ method: "POST", path: "/recipes/1/cook", body: { portions: 1 } })).status, 200);
+  assert.equal((await cook({ method: "POST", path: "/orders", body: {} })).status, 403);
+  assert.equal((await cook({ method: "POST", path: "/stocktakes", body: { location: "dry" } })).status, 403);
+  assert.equal((await cook({ method: "POST", path: "/jobs/nightly" })).status, 403);
+});
+
+test("changes are audited, newest first, for managers only", async () => {
+  const { raw, handle } = app();
+  await as("cook", raw)({ method: "POST", path: "/recipes/1/cook", body: { portions: 1 } });
+  await as("viewer", raw)({ method: "POST", path: "/jobs/nightly" });
+  await as("viewer", raw)({ path: "/items" });
+  const log = (await handle({ path: "/audit" })).body;
+  assert.equal(log.length, 2);
+  assert.deepEqual(log.map((e) => [e.key, e.method, e.path, e.status]), [
+    ["viewer", "POST", "/jobs/nightly", 403],
+    ["cook", "POST", "/recipes/1/cook", 200],
+  ]);
+  assert.match(log[0].at, /^2026-10-28T10:00:00/);
+});
